sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float targetHue;
uniform float range;
uniform float softness;
uniform float minSat;
uniform float hueShift;
uniform float saturation;
uniform float lightness;
uniform float showMatte;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 rgb2hsv(float3 c) {
    float4 K = float4(0.0, -0.3333333, 0.6666667, -1.0);
    float4 p = mix(float4(c.b, c.g, K.w, K.z), float4(c.g, c.b, K.x, K.y), step(c.b, c.g));
    float4 q = mix(float4(p.x, p.y, p.w, c.r), float4(c.r, p.y, p.z, p.x), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    return float3(abs(q.z + (q.w - q.y) / (6.0 * d + 0.0000001)), d / (q.x + 0.0000001), q.x);
}
float3 hsv2rgb(float3 c) {
    float3 p = abs(fract(float3(c.x) + float3(1.0, 0.6666667, 0.3333333)) * 6.0 - 3.0);
    return c.z * mix(float3(1.0), saturate(p - 1.0), c.y);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float3 h = rgb2hsv(s);
    float d = abs(fract(h.x - targetHue / 360.0 + 0.5) - 0.5) * 360.0;
    float w = 1.0 - smoothstep(range * (1.0 - softness), range + 0.001, d);
    w *= smoothstep(0.0, minSat + 0.001, h.y);
    float3 hh = h;
    hh.x = fract(h.x + hueShift * w / 360.0 + 1.0);
    hh.y = saturate(h.y * (1.0 + saturation * w));
    float3 o = hsv2rgb(hh);
    o = lightness >= 0.0 ? mix(o, float3(1.0), lightness * w) : o * (1.0 + lightness * w);
    if (showMatte > 0.5) o = float3(w);
    return fin(c, float4(saturate(o) * c.a, c.a), opacity);
}
